/**
 * One scenario per check of cash-seam-build-standard.
 *
 * Generated by `npx @aipathway/conformance init cash-seam-build-standard`, from
 * https://aipathway.com.au/explore-ai/cash-seam-build-standard
 *
 * The checks themselves are NOT in this file. They are fetched at run time, so
 * a correction published on the site reaches you without anybody releasing
 * anything, and you cannot end up conformant against a stale copy. What is here
 * is the part only you can write: the world each check starts in, how your build
 * is driven, and what "held" means.
 *
 * The runner delivers named events one at a time and runs the build once per
 * event. Between events it plays the outside world: the job system announcing
 * a new client engagement, the accounts officer sending the quote for it (it keeps
 * sending with a person), the client accepting, the job system closing the
 * billing period, and the clock passing the due date. Timesheet Billing
 * is the job_completed hop; the others are stand-ins (see build.mjs).
 *
 * Checks that only run against the live provider are kept apart, in
 * `liveScenarios` below. On the stub the runner reports them as `with_us`.
 */

import { CashSeamWorld } from "@aipathway/conformance";
import { releaseQuoteByPerson } from "./build.mjs";

const DAY = 86_400_000;
/** The owners the stub business set per stage (Priya, Sam, Lee). */
const DEFAULT_OWNERS = new CashSeamWorld().owners;
const QUOTE_PERSON = DEFAULT_OWNERS.quote;

async function deliver(world, build, name, via, payload = {}) {
  const ev = world.makeEvent(name, via, payload);
  world.deliver(ev);
  await build(world.ports());
  world.settle();
  world.advance(60_000);
  return ev;
}

/** The job system fires job_created for every job it has not announced yet. */
async function announce(world, build) {
  for (const j of world.unannouncedJobs()) await deliver(world, build, "job_created", "webhook", { jobId: j.id });
}

/** The person sends the draft; the customer accepts what reached them. */
async function personSendsAndCustomerAccepts(world, jobId) {
  for (const id of await releaseQuoteByPerson(world.ports(), jobId, QUOTE_PERSON)) world.accept(id);
}

/** One enquiry through the whole path, from the call to the chase. */
async function fullChain(world, build, { phone, customerName }) {
  await deliver(world, build, "call_received", "webhook", { phone, customerName, door: "phone" });
  const jobIds = world.jobsFor(phone).map((j) => j.id);
  await announce(world, build);
  for (const id of jobIds) {
    await personSendsAndCustomerAccepts(world, id);
    for (const q of world.quotesFor(id).filter((x) => x.status === "accepted")) await deliver(world, build, "quote_accepted", "webhook", { quoteId: q.id });
    world.complete(id);
    await deliver(world, build, "job_completed", "webhook", { jobId: id });
  }
  return jobIds;
}

async function overdue(world, build) {
  world.advance(15 * DAY);
  await deliver(world, build, "invoice_overdue", "schedule");
}

const describe = (world) =>
  `${world.calls.length} port call(s); jobs ${world.jobs.length}, quotes ${world.quotes.length}, invoices ${world.invoices.length}, chases ${world.chases.length}, escalations ${world.escalations.map((e) => `${e.stage}:${e.reason}@${e.ref}/${e.owner}`).join(" ") || "none"}`;

const evName = (world, id) => world.eventById(id)?.name;
const writes = (world) => world.calls.filter((c) => ["write_job", "draft_quote", "write_invoice"].includes(c.port));
const sendCalls = (world) => world.calls.filter((c) => c.port === "issue_notice" || c.port === "send_sms");

export const scenarios = [
  {
    checkId: "identity-from-the-system-of-record",
    // 1. Every downstream step takes its id from the system of record, never from a name or a phone number
    //
    // Conformance:  Once a job exists, every later step reads the upstream record's id from the job system or the ledger: from the event that woke it, or from a read of that record by id. It never mints its own key and never matches on a customer name or a phone number.
    // Inject:       Two open jobs for two different customers who share a name. One of them has a quote accepted, and the job is completed.
    // Then assert:  The quote carries its job's id from the job system and the invoice carries that quote's id and that job's id. No search by name or phone runs while a downstream event is handled. An invoice on the other customer's job, or any reference that is not an id the system issued, fails.
    world: () =>
      new CashSeamWorld({
        jobs: [
          { id: "JS-0501", customerName: "J. Lee", phone: "+61400000101", status: "open" },
          { id: "JS-0502", customerName: "J. Lee", phone: "+61400000102", status: "open" },
        ],
      }),
    drive: async (build, world) => {
      await deliver(world, build, "job_created", "webhook", { jobId: "JS-0501" });
      await deliver(world, build, "job_created", "webhook", { jobId: "JS-0502" });
      await personSendsAndCustomerAccepts(world, "JS-0501");
      world.complete("JS-0501");
      await deliver(world, build, "job_completed", "webhook", { jobId: "JS-0501" });
    },
    holds: (world) => {
      const issued = world.issuedIds();
      const q = world.quotesFor("JS-0501");
      const inv = world.invoices;
      const searchesDownstream = world.calls.filter((c) => c.port === "read_job" && c.request?.search && c.request.eventName !== "call_received");
      return (
        q.length === 1 &&
        q[0].status === "accepted" &&
        inv.length === 1 &&
        inv[0].jobId === "JS-0501" &&
        inv[0].quoteId === q[0].id &&
        world.invoicesFor("JS-0502").length === 0 &&
        searchesDownstream.length === 0 &&
        world.quotes.every((x) => issued.has(x.jobId)) &&
        inv.every((i) => issued.has(i.jobId) && (i.quoteId === null || issued.has(i.quoteId)))
      );
    },
    describe,
  },
  {
    checkId: "one-job-per-enquiry",
    // 2. One job per enquiry: a repeat call or a second door attaches to the open job
    //
    // Conformance:  Before writing a job, the build reads for an open job on that customer or number. A repeat call, or the same customer arriving through a second door, attaches to the open job with duplicate_of set. A second job is a fail.
    // Inject:       The same caller rings twice in one evening: once on the phone line, then again through the web form, from the same number.
    // Then assert:  Exactly one job exists for that number. The second enquiry carries duplicate_of with the first job's id. A read for open jobs on that number preceded every job write. A second job, or a job write with no read before it, fails.
    world: () => new CashSeamWorld(),
    drive: async (build, world) => {
      await deliver(world, build, "call_received", "webhook", { phone: "+61400000201", customerName: "M. Lee", door: "phone" });
      world.advance(2 * 60 * 60_000);
      await deliver(world, build, "call_received", "webhook", { phone: "+61400000201", customerName: "M. Lee", door: "web" });
    },
    holds: (world) => {
      const jobs = world.jobsFor("+61400000201");
      const [first, second] = world.enquiries;
      const ok = world.calls.every((c, i) => {
        if (c.port !== "write_job") return true;
        return world.calls.slice(0, i).some((r) => r.port === "read_job" && r.request?.search?.phone === "+61400000201" && r.request.search.status === "open");
      });
      return jobs.length === 1 && Boolean(first) && Boolean(second) && !first.duplicateOf && second.duplicateOf === jobs[0].id && ok;
    },
    describe,
  },
  {
    checkId: "no-external-id-no-write",
    // 3. A write that comes back without an external id is treated as not written
    //
    // Conformance:  A write into the job system or the ledger that returns a null or missing external_id did not happen, as far as the chain is concerned. The build escalates it and nothing downstream acts on it: no quote from that job, no send of that quote, no chase of that invoice.
    // Inject:       The full chain, with the runner injecting a null external_id on the quote write for one job and on the invoice write for another.
    // Then assert:  Each null write is escalated with reason write_failed. Nothing is released, sent or chased for either job, and no later record carries a null or invented reference in its place. Treating the null as a success fails.
    // On the stub:  The stub returns a null id when the runner tells it to. Only a real job system and a real ledger show the ways a real write comes back without one: a timeout after the record was made, an empty body on a success code, a rate limit mid-batch.
    //
    // Job ids are deterministic in the stub: the first job written is JS-1001, the second JS-1002.
    // "Nothing released, sent or chased" is read as downstream of the null write: JS-1002's quote
    // left before its invoice write failed, and must; no invoice or chase may follow for it.
    world: () => new CashSeamWorld({ nullQuoteFor: ["JS-1001"], nullInvoiceFor: ["JS-1002"] }),
    drive: async (build, world) => {
      await fullChain(world, build, { phone: "+61400000301", customerName: "A. Quote" });
      await fullChain(world, build, { phone: "+61400000302", customerName: "B. Invoice" });
      await overdue(world, build);
    },
    holds: (world) => {
      const issued = world.issuedIds();
      const failedQuote = world.escalations.some((e) => e.stage === "quote" && e.ref === "JS-1001" && e.reason === "write_failed");
      const failedInvoice = world.escalations.some((e) => e.stage === "invoice" && e.ref === "JS-1002" && e.reason === "write_failed");
      const nothingForA = world.quotesFor("JS-1001").length === 0 && world.invoicesFor("JS-1001").length === 0 && !world.releases.some((r) => r.kind === "quote" && r.id === null);
      const nothingForB = world.invoicesFor("JS-1002").length === 0 && !world.releases.some((r) => r.kind !== "quote" && (r.id === null || !issued.has(r.id))) && world.chases.length === 0;
      const noInvented =
        world.quotes.every((q) => q.jobId && issued.has(q.jobId)) &&
        world.invoices.every((i) => i.jobId && issued.has(i.jobId)) &&
        world.sends.every((s) => s.id && issued.has(s.id)) &&
        world.releases.every((r) => r.id && issued.has(r.id));
      return failedQuote && failedInvoice && nothingForA && nothingForB && noInvented;
    },
    describe,
  },
  {
    checkId: "the-chain-carries-the-id",
    // 4. The quote carries the job id, the invoice carries the quote or job id, and the chase reads the invoice id off the live ledger
    //
    // Conformance:  Each record carries the id of the one before it. The quote names the job. The invoice names the accepted quote and the job. The chase names an invoice id the ledger returned when the build read it. A break anywhere in the chain is a fail.
    // Inject:       One enquiry through the whole path: the job is created, the quote is accepted, the job is completed and the invoice goes overdue.
    // Then assert:  Exactly one job, one quote, one invoice and one chase exist. The quote's job id is the job's id, the invoice's quote id and job id are those records' ids, and the chase's invoice id appeared in a ledger read made before it. Any missing or mismatched link fails.
    world: () => new CashSeamWorld(),
    drive: async (build, world) => {
      await fullChain(world, build, { phone: "+61400000401", customerName: "C. Chain" });
      await overdue(world, build);
    },
    holds: (world) => {
      if (world.jobs.length !== 1 || world.quotes.length !== 1 || world.invoices.length !== 1 || world.chases.length !== 1) return false;
      const [job] = world.jobs;
      const [quote] = world.quotes;
      const [inv] = world.invoices;
      const [chase] = world.chases;
      const chaseCall = world.calls.findIndex((c) => c.port === "send_sms" && c.request?.send === "chase");
      const readBefore = world.calls.slice(0, chaseCall).some((c) => c.port === "read_ledger" && (c.response?.ids ?? []).includes(chase.invoiceId));
      return quote.jobId === job.id && inv.quoteId === quote.id && inv.jobId === job.id && chase.invoiceId === inv.id && chaseCall > 0 && readBefore;
    },
    describe,
  },
  {
    checkId: "confirmation-is-not-a-write",
    // 5. A chat or connector confirmation is not a write and not a release
    //
    // Conformance:  A write counts only when it is read back through the port from the system of record. Every send to the customer, the quote, the invoice and the chase, waits for a release that names a person or a named rule. The model saying it is done is neither.
    // Inject:       The full chain, with the runner making one quote write return an id and a success message while storing nothing, as a connector that answered before the record existed would.
    // Then assert:  That quote is escalated and never released or sent. Every send was preceded by a read through the port that returned the record, and by a release naming a person or a rule the business set. A send with no read-back, or a release with neither a person nor a rule, fails.
    // On the stub:  The stub proves the read-back and the release are on the trace. Only a real tenant proves the record read back is the record the customer will see, and that the release came from the person or rule it names.
    world: () => new CashSeamWorld({ phantomQuoteFor: ["JS-1001"] }),
    drive: async (build, world) => {
      await fullChain(world, build, { phone: "+61400000501", customerName: "D. Phantom" });
      await fullChain(world, build, { phone: "+61400000502", customerName: "E. Real" });
      await overdue(world, build);
    },
    holds: (world) => {
      const [ghost] = world.phantomIds;
      if (!ghost) return false;
      const escalated = world.escalations.some((e) => e.stage === "quote" && e.ref === "JS-1001" && (e.detail ?? "").includes(ghost));
      const ghostUntouched = !world.releases.some((r) => r.id === ghost) && !world.sends.some((s) => s.id === ghost);
      const people = new Set(Object.values(world.owners));
      const ruleName = world.releaseRule?.name;
      const sends = sendCalls(world);
      const everySendGated = sends.every((s) => {
        const i = world.calls.indexOf(s);
        const before = world.calls.slice(0, i);
        const id = s.request.id;
        const readBack = before.some(
          (c) =>
            (c.port === "read_job" && c.request?.quote === id && c.response?.id === id) ||
            (c.port === "read_ledger" && ((c.request?.invoice === id && c.response?.id === id) || (c.response?.ids ?? []).includes(id))),
        );
        const released = before.some(
          (c) => c.port === "gate" && c.request.release === s.request.send && c.request.id === id && ((c.request.person && people.has(c.request.person)) || (c.request.rule && c.request.rule === ruleName)),
        );
        return readBack && released;
      });
      const everyReleaseNamed = world.releases.every((r) => (r.person && people.has(r.person)) || (r.rule && r.rule === ruleName));
      return escalated && ghostUntouched && sends.length > 0 && everySendGated && everyReleaseNamed && world.chases.length === 1;
    },
    describe,
  },
  {
    checkId: "named-unattended-trigger",
    // 6. Every hop starts from a named event, and none waits for a chat session
    //
    // Conformance:  Each hop is woken by a named event arriving by webhook, schedule or polling: job created, quote accepted, job completed, invoice overdue. A build that only moves while somebody has a chat window open fails, and so does one that acts on a chat message as if it were an event.
    // Inject:       The full chain delivered as events with nobody in a session, plus one chat message asking for an invoice to be raised.
    // Then assert:  Every write and every chase names the event that woke it, the event is one the runner delivered by webhook, schedule or polling, and each hop's event is the right kind for that hop. All four hops happen. A hop missing, or a write woken by the chat message, fails.
    // On the stub:  The stub delivers the events itself. Only production proves the webhook is registered, the schedule actually fires overnight, and the poll survives a restart with nobody watching.
    world: () => new CashSeamWorld(),
    drive: async (build, world) => {
      const phone = "+61400000601";
      await deliver(world, build, "call_received", "webhook", { phone, customerName: "F. Event", door: "phone" });
      await announce(world, build);
      const [job] = world.jobsFor(phone);
      // Somebody types into a chat window before the job is done. It must not raise anything.
      await deliver(world, build, "chat_message", "chat", { text: `Can you raise the invoice for ${job?.id} now?`, jobId: job?.id });
      await personSendsAndCustomerAccepts(world, job.id);
      world.complete(job.id);
      await deliver(world, build, "job_completed", "webhook", { jobId: job.id });
      await overdue(world, build);
    },
    holds: (world) => {
      const KIND = { write_job: "call_received", draft_quote: "job_created", write_invoice: "job_completed" };
      const unattended = (id) => {
        const ev = world.eventById(id);
        return Boolean(ev) && ["webhook", "schedule", "poll"].includes(ev.via);
      };
      const writesOk = writes(world).every((c) => unattended(c.request.trigger) && evName(world, c.request.trigger) === KIND[c.port]);
      const chasesOk = world.chases.every((c) => unattended(c.trigger) && evName(world, c.trigger) === "invoice_overdue");
      const chat = world.delivered.find((e) => e.name === "chat_message");
      const noChatWrite = ![...writes(world).map((c) => c.request.trigger), ...world.chases.map((c) => c.trigger), ...world.sends.map((s) => s.trigger)].includes(chat?.id);
      const allFour = world.jobs.length === 1 && world.quotes.length === 1 && world.invoices.length === 1 && world.chases.length === 1;
      const jobTrig = world.jobs[0]?.trigger, quoteTrig = world.quotes[0]?.trigger, invTrig = world.invoices[0]?.trigger;
      const recordsNamed = evName(world, jobTrig) === "call_received" && evName(world, quoteTrig) === "job_created" && evName(world, invTrig) === "job_completed";
      return writesOk && chasesOk && noChatWrite && allFour && recordsNamed;
    },
    describe,
  },
  {
    checkId: "exception-owner-travels",
    // 7. An exception names its owner, travels with the record, and the next step does not pass it
    //
    // Conformance:  A parked or escalated item names the person who owns it, taken from the owners the business set for that stage. The exception stays on the record, and the next step reads it and stops rather than proceeding past it.
    // Inject:       Two jobs complete. One already carries an open exception a person set on it. The invoice write for the other comes back with no external id.
    // Then assert:  No invoice is raised for the job carrying the exception, and a hold names that exception's owner. The failed write is escalated naming the owner the business set for invoices. An escalation with no owner, an owner the business never named, or an invoice raised past the exception, fails.
    world: () =>
      new CashSeamWorld({
        jobs: [
          { id: "JS-0701", customerName: "G. Held", phone: "+61400000701", status: "complete", exception: { reason: "disputed_scope", owner: DEFAULT_OWNERS.quote } },
          { id: "JS-0702", customerName: "H. Null", phone: "+61400000702", status: "complete" },
        ],
        nullInvoiceFor: ["JS-0702"],
      }),
    drive: async (build, world) => {
      await deliver(world, build, "job_completed", "webhook", { jobId: "JS-0701" });
      await deliver(world, build, "job_completed", "webhook", { jobId: "JS-0702" });
    },
    holds: (world) => {
      const named = new Set(Object.values(world.owners));
      const hold = world.escalations.some((e) => e.ref === "JS-0701" && e.owner === DEFAULT_OWNERS.quote);
      const failed = world.escalations.some((e) => e.ref === "JS-0702" && e.stage === "invoice" && e.reason === "write_failed" && e.owner === world.owners.invoice);
      const everyOwned = world.escalations.every((e) => e.owner && named.has(e.owner));
      const travels = world.job("JS-0702")?.exception?.owner === world.owners.invoice && world.job("JS-0701")?.exception?.owner === DEFAULT_OWNERS.quote;
      return world.invoicesFor("JS-0701").length === 0 && world.invoices.length === 0 && hold && failed && everyOwned && travels;
    },
    describe,
  },
  {
    checkId: "survives-the-builder",
    // 8. It survives the builder
    //
    // Conformance:  Someone other than the builder can explain what it does, and it runs on an account the business owns.
    // Inject:       No stimulus. The builder names who else can explain it and whose account each hop's trigger and the writes into the job system and the ledger runs on.
    // Then assert:  The runner reports what was declared and never scores it green on its own say-so.
    // On the stub:  Not a runtime property. Software cannot prove a second person understands it, and outliving its author is precisely what is being asked about.
    world: () => new CashSeamWorld(),
    drive: () => {},
    // Never green on a declaration. The business running the node attaches its own evidence.
    holds: () => false,
    describe: () =>
      "Declared: the code is public in mesh/nodes/timesheet-billing and maintained by AI Pathway (digitalgym). The trigger and every write run on the business's own job system and ledger accounts. Not scored: the business attaches who else can explain it.",
  },
];

// The checks a stub cannot pass, and is not asked to. Check 9 runs only on the
// business's own job system and ledger, and reports with_us on the stub.
export const liveScenarios = [
  {
    checkId: "pass-test",
    // 9. The pass test passes
    //
    // Conformance:  On the business's own job system and ledger: the same caller rings twice, the quote is accepted, the job completes and the invoice goes overdue. Exactly one job, one quote, one invoice and one chase exist, each carrying the upstream id. A null external id injected anywhere stops the chain.
    // Inject:       Real events on the real tenant: two real calls from one number, a real acceptance, a real completion, a real due date passing, then the same run again with one write forced to return no id.
    // Then assert:  Each record in the job system and the ledger holds the id of the one before it, as issued by those systems. The second call attached to the first job. The forced null produced an escalation with an owner and nothing downstream of it.
    // On the stub:  Deliberately unpassable on a stub. A stub issues whatever ids it likes and links whatever it is told to, so a build can agree with itself there and still key the real invoice to a name. Only the business's own systems prove the id that left one hop is the id that arrived at the next.
    world: () => new CashSeamWorld(),
    drive: (build, world) => build(world.ports()),
    holds: () => false,
    describe: (world) => `${world.calls.length} port call(s)`,
  },
];
